
.discover-screen {
  display: flex;
  flex-direction: column;
  gap: 18px;
  padding: 18px 20px 40px;
  color: #f8fafc;
}

.discover-header {
  position: sticky;
  top: 0;
  z-index: 20;
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding-bottom: 8px;
  background: rgba(10, 12, 22, 0.8);
  backdrop-filter: blur(18px);
}

.header-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}

.page-title {
  display: flex;
  align-items: center;
  gap: 10px;
}

.page-title .material-symbols-outlined {
  color: rgba(167, 139, 250, 0.95);
}

.title-text {
  font-size: 18px;
  font-weight: 700;
}

.title-sub {
  font-size: 12px;
  color: rgba(148, 163, 184, 0.85);
}

.header-actions {
  display: flex;
  gap: 10px;
}

.ghost-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 12px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.05);
  color: #e2e8f0;
  font-size: 12px;
}

.search-shell {
  position: relative;
}

.search-glow {
  position: absolute;
  inset: -6px;
  border-radius: 18px;
  background: linear-gradient(120deg, rgba(127, 19, 236, 0.4), rgba(99, 102, 241, 0.15));
  filter: blur(16px);
  opacity: 0.4;
}

.search-bar {
  position: relative;
  display: flex;
  align-items: center;
  gap: 10px;
  height: 50px;
  border-radius: 16px;
  padding: 0 12px;
}

.search-bar input {
  flex: 1;
  background: transparent;
  border: none;
  color: #fff;
  font-size: 13px;
  outline: none;
}

.search-bar input::placeholder {
  color: rgba(148, 163, 184, 0.85);
}

.search-bar .accent {
  color: rgba(167, 139, 250, 0.95);
}

.search-action {
  width: 36px;
  height: 36px;
  border-radius: 12px;
  border: 1px solid rgba(127, 19, 236, 0.35);
  background: rgba(127, 19, 236, 0.2);
  color: #e9d5ff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.chip-row {
  display: flex;
  gap: 10px;
  overflow-x: auto;
  padding-bottom: 4px;
}

.chip {
  padding: 6px 14px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(30, 20, 45, 0.7);
  color: rgba(203, 213, 225, 0.8);
  font-size: 12px;
  white-space: nowrap;
}

.chip.active {
  border-color: rgba(127, 19, 236, 0.5);
  background: rgba(127, 19, 236, 0.2);
  color: #fff;
  box-shadow: 0 0 14px rgba(127, 19, 236, 0.35);
}

.toolbar-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}

.toolbar-hint {
  font-size: 11px;
  color: rgba(148, 163, 184, 0.8);
}

.sort-control {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  color: rgba(203, 213, 225, 0.8);
}

.sort-select {
  background: rgba(15, 10, 30, 0.8);
  border: 1px solid rgba(148, 163, 184, 0.3);
  color: #e2e8f0;
  border-radius: 10px;
  padding: 4px 8px;
  font-size: 11px;
}

.discover-content {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.shop-masonry {
  columns: 2;
  column-gap: 14px;
}

.shop-card {
  position: relative;
  break-inside: avoid;
  margin-bottom: 14px;
  border-radius: 18px;
  overflow: hidden;
  cursor: pointer;
  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease;
}

.shop-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 16px 28px rgba(10, 10, 20, 0.35);
}

.shop-cover {
  width: 100%;
}

.shop-cover.aspect-tall {
  aspect-ratio: 3 / 5;
}

.shop-cover.aspect-square {
  aspect-ratio: 1 / 1;
}

.shop-cover.aspect-wide {
  aspect-ratio: 4 / 3;
}

.shop-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(10, 10, 22, 0.05), rgba(10, 10, 22, 0.78));
}

.shop-content {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.shop-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.shop-name {
  font-size: 14px;
  font-weight: 700;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.shop-rating {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  color: #facc15;
  font-weight: 600;
}

.shop-rating .fill {
  font-variation-settings:
    'FILL' 1,
    'wght' 600,
    'opsz' 18;
  font-size: 14px;
}

.shop-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.tag {
  font-size: 10px;
  padding: 3px 8px;
  border-radius: 999px;
  background: rgba(127, 19, 236, 0.2);
  color: rgba(216, 180, 254, 0.95);
}

.tag.muted {
  background: rgba(148, 163, 184, 0.2);
  color: rgba(226, 232, 240, 0.75);
}

.shop-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 11px;
  color: rgba(203, 213, 225, 0.85);
}

.delete-btn {
  position: absolute;
  top: 10px;
  right: 10px;
  width: 32px;
  height: 32px;
  border-radius: 999px;
  border: 1px solid rgba(239, 68, 68, 0.4);
  background: rgba(239, 68, 68, 0.2);
  color: #fecaca;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  padding: 40px 12px;
  text-align: center;
  color: rgba(226, 232, 240, 0.7);
}

.btn-primary {
  border: none;
  border-radius: 999px;
  padding: 10px 16px;
  background: linear-gradient(135deg, #7f13ec, #6c4bff);
  color: #fff;
  font-size: 12px;
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.hide-scrollbar::-webkit-scrollbar {
  display: none;
}

.hide-scrollbar {
  scrollbar-width: none;
}

.hidden-input {
  display: none;
}

@media (min-width: 960px) {
  .shop-masonry {
    columns: 3;
  }
}
